from django.http import HttpResponse, JsonResponse
from django.urls import reverse
from django.utils import six
from django.utils.encoding import force_text
from django.utils.http import urlquote
from django.utils.translation import ugettext, ugettext_lazy

GREETING = ugettext_lazy("Hello")


def greet(name):
    return "%s, %s!" % (ugettext("Hello"), name)


def greeting_label():
    return force_text(GREETING)


def to_text(value):
    return force_text(value)


def is_text(value):
    return isinstance(value, six.string_types)


def search_link(term):
    return "/search/?q=" + urlquote(term)


def hello_view(request, name):
    if request.is_ajax():
        return JsonResponse({"greeting": greet(name)})
    return HttpResponse(greet(name))


def hello_url(name):
    return reverse("hello", kwargs={"name": name})

