import json

from django.test import RequestFactory

from app.core import (
    greet, greeting_label, hello_url, hello_view, is_text, search_link, to_text,
)


def test_greet():
    assert greet("Ada") == "Hello, Ada!"
    assert greeting_label() == "Hello"


def test_to_text():
    assert to_text(b"caf\xc3\xa9") == "café"
    assert to_text(12) == "12"
    assert is_text("x") and not is_text(b"x")


def test_search_link():
    assert search_link("a b&c") == "/search/?q=a%20b%26c"


def test_hello_url_and_view():
    url = hello_url("ada")
    assert url == "/hello/ada/"
    request = RequestFactory().get(url)
    assert hello_view(request, "ada").content == b"Hello, ada!"


def test_hello_view_ajax():
    request = RequestFactory().get("/hello/ada/", HTTP_X_REQUESTED_WITH="XMLHttpRequest")
    assert json.loads(hello_view(request, "ada").content) == {"greeting": "Hello, ada!"}

